window.CA = {"date": "Thursday, 09 July 2026", "updated": "2026-07-09 04:11", "updated_label": "09 Jul 2026, 04:11 IST", "items": [{"title": "PM Modi Visits Indonesia: BrahMos Missile Deal Signed, Prambanan Temple Visit Highlights Cultural Ties", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi concluded his visit to Indonesia with the signing of key agreements, including Indonesia's purchase of BrahMos supersonic cruise missiles. Modi visited the Prambanan Temple complex, emphasising shared cultural heritage between India and Indonesia. The visit marks a significant deepening of defence and cultural ties between the two nations.", "exam_angle": "BrahMos exports strengthen India's defence diplomacy and 'Make in India' in defence; India-Indonesia relations are important for Indo-Pacific strategy and ASEAN engagement.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indonesia to purchase BrahMos supersonic cruise missiles from India", "PM Modi visited Prambanan Temple — a UNESCO World Heritage Hindu temple complex in Java", "BrahMos is a joint venture between India's DRDO and Russia's NPO Mashinostroyenia", "Visit part of broader India-ASEAN and Indo-Pacific outreach"], "source": "The Hindu / Indian Express", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "PM Modi's Australia Visit: Uranium Deal and Defence Ties on Agenda", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi is scheduled to visit Australia, with uranium supply and defence cooperation featuring prominently on the agenda. The visit is expected to further cement the Comprehensive Strategic Partnership between India and Australia. Discussions are also expected to cover trade, technology, and collaboration under the Quad framework.", "exam_angle": "India-Australia relations are key for UPSC IR; uranium deal is significant for India's civil nuclear energy programme; Australia is a member of Quad alongside India, US, and Japan.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India and Australia share a Comprehensive Strategic Partnership (since 2020)", "Australia is one of the world's largest uranium exporters", "Both are members of the Quad grouping", "India requires uranium imports to fuel its nuclear power plants under civilian nuclear agreements"], "source": "Hindustan Times", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "US Indicts Lawrence Bishnoi Gang Over Hardeep Singh Nijjar's Murder in Canada", "category": "ir", "category_name": "International Relations", "summary": "US prosecutors have charged Indian gangster Lawrence Bishnoi and associates, including Goldy Brar and Rohit Godara (linked to Bhagwanpuria gang), with organising the murder of Sikh activist Hardeep Singh Nijjar in Canada. A Punjab Police SHO was also among 37 individuals named by the US. Canada's police separately stated that their 'Operation Hard Ball' investigation found no evidence directly linking the Indian government to Nijjar's killing.", "exam_angle": "Relevant to India-Canada diplomatic tensions, extraterritorial jurisdiction, India-US law enforcement cooperation, and the ongoing Khalistan issue in India's foreign policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Hardeep Singh Nijjar was a Khalistani activist killed in Surrey, Canada in June 2023", "US indicted Lawrence Bishnoi gang; 37 individuals named including a Punjab Police SHO", "Canada's 'Operation Hard Ball' found no direct evidence linking Indian government to the killing", "Lawrence Bishnoi is currently lodged in Indian jail; his gang is linked to multiple high-profile crimes in India"], "source": "The Hindu / BBC / The Guardian", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "CSIR-NAL Completes Design of Indigenous 19-Seater Saras MkII Light Transport Aircraft", "category": "scitech", "category_name": "Science & Technology", "summary": "The Council of Scientific and Industrial Research – National Aerospace Laboratories (CSIR-NAL) has completed the design of the Saras MkII, an indigenous 19-seater light transport aircraft. The development is a significant milestone for India's civilian aircraft manufacturing capability. The minister described it as a major step towards Atmanirbhar Bharat in aviation.", "exam_angle": "Relevant to India's self-reliance in aerospace/defence manufacturing, CSIR-NAL's role in indigenous aviation technology, and GS Paper 3 science-tech topics.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Developed by: CSIR-National Aerospace Laboratories (CSIR-NAL), Bengaluru", "Aircraft: Saras MkII — 19-seater light transport aircraft", "Saras is India's first indigenously designed and developed civil aircraft", "Significance: Part of Atmanirbhar Bharat initiative in aerospace sector"], "source": "The Times of India", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "India Monitoring Strait of Hormuz Amid Escalating US-Iran Conflict", "category": "defence", "category_name": "Defence & Security", "summary": "India is closely monitoring the Strait of Hormuz following recent ship attacks and fresh US military strikes on Iran after President Trump declared the Iran ceasefire 'over'. The Strait of Hormuz is critical for India's energy security, as a large portion of India's oil imports pass through it. The escalation has also caused Indian stock markets to crash, with Sensex falling over 1,700 points.", "exam_angle": "Strait of Hormuz is critical for India's energy security; US-Iran escalation impacts global oil prices, India's current account deficit, and maritime security (relevant for GS Paper 2 IR and GS Paper 3 Economy).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Strait of Hormuz: narrow waterway between Iran and Oman; ~20% of global oil trade passes through it", "India imports ~85% of its crude oil needs; significant share transits via Hormuz", "Trump declared Iran ceasefire 'over'; US launched fresh strikes on Iran", "Sensex fell over 1,700 points; oil prices jumped ~5% on escalation fears"], "source": "The Economic Times", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "IMF Lowers 2026 Global Growth Forecast to 3%; India's GDP Forecast Marginally Reduced", "category": "economy", "category_name": "Economy & Banking", "summary": "The International Monetary Fund (IMF) has revised its 2026 global growth forecast downward to 3%, citing the impact of the US-Iran war escalation on energy prices and global trade. India's GDP growth forecast was also marginally reduced, though India was still identified as among the fastest-growing major economies. The IMF sees a rebound in 2027.", "exam_angle": "IMF growth forecasts are standard exam facts; global growth slowdown impacts India's exports and current account; relevant to GS Paper 3 (Economy) and GS Paper 2 (IR — multilateral institutions).", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["IMF 2026 global growth forecast: 3% (revised downward)", "Reason for downward revision: US-Iran conflict, rising oil prices, trade disruptions", "India remains among the fastest-growing major economies despite marginal cut", "IMF projects a rebound in global growth in 2027"], "source": "Reuters / The Times of India", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "India's Gross Enrolment Ratio (GER) in Higher Education Hits 30%, But Lags 2035 Target", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India's Gross Enrolment Ratio (GER) in higher education has reached 30%, a milestone in expanding access to tertiary education. However, the current pace of growth is insufficient to achieve the National Education Policy (NEP) 2020 target of 50% GER by 2035. The data highlights the need for accelerated investment in higher education infrastructure.", "exam_angle": "GER is a key indicator for education policy; NEP 2020 set a target of 50% GER by 2035; relevant to GS Paper 2 (Social Issues — Education).", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Current GER in higher education: 30%", "NEP 2020 target: 50% GER in higher education by 2035", "GER = ratio of total enrolment in a specific level of education to the population of the age group corresponding to that level", "India has the world's largest higher education system by number of institutions"], "source": "The Times of India", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "Allahabad High Court: Child Marriage Prohibition Act Applies to All Religions", "category": "polity", "category_name": "Polity & Governance", "summary": "The Allahabad High Court has ruled that the Prohibition of Child Marriage Act (PCMA) applies to all religions in India, including Muslims. The court held that no personal law can override the secular statutory law protecting children from early marriage. This ruling has significant implications for the debate on a Uniform Civil Code and child rights.", "exam_angle": "Critical for GS Paper 2 Polity — intersection of personal laws, secular legislation, and child rights; also relevant to UCC debate and Supreme Court's earlier judgments on PCMA.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Court: Allahabad High Court", "Law in question: Prohibition of Child Marriage Act (PCMA), 2006", "Ruling: PCMA applies to all religions; personal law cannot override it", "Minimum age of marriage in India: 18 for women, 21 for men (proposed increase to 21 for women pending)"], "source": "NDTV", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "RBI and Government Back Crypto Ban; Tax Department Warns of Evasion Risks", "category": "economy", "category_name": "Economy & Banking", "summary": "The Reserve Bank of India (RBI) has reiterated its support for a complete ban on private cryptocurrencies in India, according to internal documents. The Income Tax Department has separately warned of significant tax evasion risks associated with crypto transactions. India currently taxes Virtual Digital Assets (VDAs) at 30% but has not enacted a comprehensive crypto regulation law.", "exam_angle": "RBI's stance on crypto is frequently asked; India's crypto taxation framework (30% tax, 1% TDS) and the pending Cryptocurrency and Regulation of Official Digital Currency Bill are key exam topics.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["RBI position: Supports ban on private cryptocurrencies", "India taxes Virtual Digital Assets (VDAs) at 30% flat rate + 1% TDS (since Budget 2022-23)", "RBI has been developing its own Central Bank Digital Currency (CBDC) — 'Digital Rupee' (e₹)", "A comprehensive crypto regulation bill is yet to be passed by Parliament"], "source": "Reuters", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "India-Maldives Begin Free Trade Agreement (FTA) Negotiations", "category": "ir", "category_name": "International Relations", "summary": "India and the Maldives have formally commenced negotiations for a Free Trade Agreement (FTA) aimed at boosting bilateral economic ties. The development comes amid the backdrop of recent strains in India-Maldives relations following the election of President Mohamed Muizzu and his 'India Out' campaign. An FTA would significantly enhance trade and investment flows between the two neighbours.", "exam_angle": "India-Maldives relations are important for 'Neighbourhood First' policy and India's Indian Ocean strategy; FTA negotiations signal renewed economic engagement; relevant for GS Paper 2 (IR).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India is Maldives' largest trading partner and a key source of tourists", "FTA negotiations signal effort to reset India-Maldives ties after 'India Out' episode", "Maldives is strategically located in the Indian Ocean, critical for India's maritime security", "India has existing FTAs with ASEAN, Sri Lanka, and is negotiating with the UK, EU, etc."], "source": "NDTV", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "India-Myanmar 23rd National Level Meeting Concludes in New Delhi", "category": "ir", "category_name": "International Relations", "summary": "The 23rd National Level Meeting between India and Myanmar was held in New Delhi, covering bilateral cooperation on border management, connectivity, and development projects. The meeting is part of regular institutional dialogue between the two countries. India shares a 1,643 km border with Myanmar across four northeastern states.", "exam_angle": "India-Myanmar relations are relevant for Act East Policy, border security, connectivity projects (Kaladan Multi-Modal Transit Transport Project, India-Myanmar-Thailand Trilateral Highway), and Northeast India development.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India shares a 1,643 km border with Myanmar (across Arunachal Pradesh, Nagaland, Manipur, Mizoram)", "Key connectivity project: Kaladan Multi-Modal Transit Transport Project", "India-Myanmar-Thailand Trilateral Highway is a major connectivity initiative", "Meeting covered border management, connectivity, and bilateral development cooperation"], "source": "PIB", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "E20 Fuel Controversy: Backlash Against Ethanol-Blended Petrol Intensifies in India", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India's rollout of E20 fuel (petrol blended with 20% ethanol) has faced significant public and industry backlash, with concerns over reduced mileage, engine compatibility, and consumer deception. Former Delhi CM Arvind Kejriwal wrote to 29 automakers seeking clarification on their vehicles' compatibility with E20. The government's National Biofuel Policy aims for 20% ethanol blending in petrol by 2025-26.", "exam_angle": "India's Ethanol Blending Programme (EBP) is a key GS Paper 3 topic covering energy policy, biofuels, and environmental sustainability; the E20 controversy raises consumer protection and regulatory issues.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20: Petrol blended with 20% ethanol", "India's target: 20% ethanol blending in petrol by 2025-26 (advanced from 2030 under National Biofuel Policy 2018)", "Ethanol blending reduces dependence on crude oil imports and lowers carbon emissions", "India achieved ~15% blending in 2023-24; E20 rollout began in select cities"], "source": "BBC / Reuters / The Times of India", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "SBI Funds Management IPO to Open on July 14; India's Largest Asset Manager Targets $1.2 Billion", "category": "economy", "category_name": "Economy & Banking", "summary": "SBI Funds Management Limited (SBIFML), the asset management arm of State Bank of India and one of India's largest mutual fund managers, has filed its Red Herring Prospectus (RHP) for an IPO opening on July 14. The issue is expected to raise approximately $1.2 billion (around Rs 10,000 crore), attracting interest from major sovereign wealth funds. This is one of the most significant financial sector IPOs in recent years.", "exam_angle": "SBI Mutual Fund is the largest AMC in India by AUM; IPO of financial sector entities is relevant to GS Paper 3 (Economy — capital markets, banking sector); SEBI's role in regulating IPOs.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["SBI Funds Management Ltd (SBIFML) is the asset management company of SBI Mutual Fund", "IPO opens: July 14; target size: ~$1.2 billion (~Rs 10,000 crore)", "SBI MF is India's largest mutual fund by Assets Under Management (AUM)", "Regulated by SEBI under SEBI (Mutual Funds) Regulations, 1996"], "source": "Moneycontrol / Reuters", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "ULPIN and DIGIPIN Integration: Department of Land Resources Meets NIUA and Department of Posts", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Department of Land Resources held a brainstorming meeting with the National Institute of Urban Affairs (NIUA) and the Department of Posts to explore the integration of ULPIN (Unique Land Parcel Identification Number) with DIGIPIN (Digital Postal Index Number). The integration aims to create a unified geospatial addressing system linking land records with postal addresses. This is a key step towards modernising India's land governance and digital public infrastructure.", "exam_angle": "ULPIN ('Bhu-Aadhar') and DIGIPIN are important digital governance initiatives; their integration is relevant for GS Paper 2 (Governance — e-governance, land reforms) and GS Paper 3 (Economy — land markets).", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["ULPIN: Unique Land Parcel Identification Number — a 14-digit unique ID for every land parcel in India (also called 'Bhu-Aadhar')", "DIGIPIN: Digital Postal Index Number — a geo-coded addressing system by India Post (10-character alphanumeric code)", "Nodal Ministry for ULPIN: Department of Land Resources (under Ministry of Rural Development)", "Integration aims to link land records with postal/geospatial addresses for better governance"], "source": "PIB", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "Sports Authority of India and Safdarjung Sports Injury Centre Sign MoU for Sports Science", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Sports Authority of India (SAI) and the Safdarjung Sports Injury Centre have signed a Memorandum of Understanding (MoU) to strengthen sports science support and athlete care in India. The collaboration aims to provide elite athletes with improved access to sports medicine, injury rehabilitation, and performance science services. This supports India's push for better Olympic and international sports performance.", "exam_angle": "SAI is the nodal body for sports development in India under the Ministry of Youth Affairs and Sports; sports science infrastructure is relevant for GS Paper 2 (Governance — sports policy).", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["MoU signed between: Sports Authority of India (SAI) and Safdarjung Sports Injury Centre", "SAI operates under: Ministry of Youth Affairs and Sports", "Objective: Strengthen sports science, injury management, and athlete care", "Safdarjung Hospital is a Central Government hospital under Ministry of Health & Family Welfare"], "source": "PIB", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "India Post Partners with Mahanagar Gas for Technology-Enabled Gas Meter Reading in Mumbai", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India Post and Mahanagar Gas Limited (MGL) have partnered to deliver technology-enabled gas meter reading services across Mumbai. India Post's vast network of postmen will be used to conduct doorstep meter readings using handheld devices, leveraging the Department of Posts' last-mile connectivity. This is part of India Post's broader initiative to leverage its network for non-postal services.", "exam_angle": "India Post's diversification into financial and utility services is relevant for GS Paper 2 (Governance); Mahanagar Gas is a city gas distribution company; demonstrates PPP model for utility services.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Partners: India Post (Department of Posts) and Mahanagar Gas Limited (MGL)", "Service: Technology-enabled gas meter reading in Mumbai", "India Post has ~1.55 lakh post offices — the world's largest postal network", "MGL is a joint venture of GAIL (India) Ltd and British Gas for city gas distribution in Mumbai"], "source": "PIB", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "Mahadev Betting App Founder Saurabh Chandrakar Arrested in Oman", "category": "polity", "category_name": "Polity & Governance", "summary": "Saurabh Chandrakar, the co-founder of the illegal Mahadev Online Book betting app, has been arrested in Oman. Chandrakar, along with Ravi Uppal, is accused of running a massive online betting and gambling racket worth thousands of crores. Indian agencies including the Enforcement Directorate (ED) had been pursuing him after he fled India; his extradition is now being sought.", "exam_angle": "Mahadev App case involves PMLA (Prevention of Money Laundering Act), ED jurisdiction, online gambling regulation, and international law enforcement cooperation — all GS Paper 2/3 topics.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Arrested: Saurabh Chandrakar, co-founder of Mahadev Online Book app", "Location of arrest: Oman", "Investigating agency in India: Enforcement Directorate (ED) under PMLA, 2002", "Case involves alleged online betting worth thousands of crores; linked to money laundering"], "source": "The Times of India", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "PM Modi Visits Exhibition Marking Golden Jubilee (60 Years) of 1965 India-Pakistan War", "category": "defence", "category_name": "Defence & Security", "summary": "Prime Minister Narendra Modi visited an exhibition organised to commemorate the Golden Jubilee of the 1965 India-Pakistan War (Operation Gibraltar / Battle of Asal Uttar). The 1965 war, fought in September, was a significant conflict where India repulsed Pakistan's offensive. The year 2025-26 marks 60 years of the war.", "exam_angle": "The 1965 war is important for defence history; key battles include Asal Uttar (Patton Nagar) and Haji Pir Pass; concluded with the Tashkent Agreement (January 1966) mediated by USSR.", "gs_paper": "GS Paper 1 (History)", "key_facts": ["1965 India-Pakistan War fought in August–September 1965", "Key Indian victories: Battle of Asal Uttar (where Pakistan's Patton tanks were destroyed), Haji Pir Pass", "War ended with Tashkent Agreement (January 10, 1966), mediated by Soviet Union", "2025-26 marks 60th anniversary (Diamond/Golden Jubilee) of the 1965 war"], "source": "The Economic Times", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "Google Selects 20 Indian AI-First Startups for 2026 India Accelerator Programme", "category": "scitech", "category_name": "Science & Technology", "summary": "Google has selected 20 Indian artificial intelligence (AI) startups for its 2026 India Accelerator cohort. The programme, part of Google for Startups Accelerator, provides mentorship, technical support, and access to Google's AI tools and cloud infrastructure. The initiative reflects India's growing prominence as an AI startup hub.", "exam_angle": "India's AI startup ecosystem and government's IndiaAI Mission are GS Paper 3 topics; Google's investment in India's digital economy is relevant to FDI and technology policy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Programme: Google for Startups Accelerator — India (2026 batch)", "Selected: 20 AI-first Indian startups", "India launched the IndiaAI Mission (2024) with Rs 10,371 crore budget for AI ecosystem development", "India ranks among the top 5 globally in AI startup ecosystem"], "source": "Deccan Herald / YourStory", "day": "2026-07-09", "day_label": "09 Jul"}, {"title": "US Charges Lawrence Bishnoi and Goldy Brar in Hardeep Singh Nijjar Murder Case; FBI Offers $50,000 Reward", "category": "ir", "category_name": "International Relations", "summary": "The United States Department of Justice has filed charges against Lawrence Bishnoi (currently imprisoned in India) and Goldy Brar for allegedly ordering and orchestrating the June 2023 murder of Canadian Sikh separatist leader Hardeep Singh Nijjar in Surrey, British Columbia. The FBI has offered a $50,000 reward for information leading to Goldy Brar's arrest. The US indictment stops short of directly accusing the Indian government, but places these gangsters at the centre of a transnational murder conspiracy. The charges follow Canada's earlier accusations against India over the Nijjar killing, which had severely strained India-Canada diplomatic relations.", "exam_angle": "Critically relevant for GS Paper 2 (International Relations) — India-Canada diplomatic crisis, transnational organised crime, and India-US relations. Also tests understanding of extradition frameworks and Five Eyes intelligence sharing.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Accused: Lawrence Bishnoi (jailed in India) and Goldy Brar", "Victim: Hardeep Singh Nijjar, killed June 2023 in Surrey, Canada", "Charged by: US Department of Justice", "FBI reward: $50,000 for Goldy Brar's arrest"], "source": "The Hindu / Reuters / The Guardian", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "US-Iran Military Strikes Escalate; Trump Declares Ceasefire Deal 'Over', Oil Prices Surge", "category": "ir", "category_name": "International Relations", "summary": "The United States and Iran exchanged military strikes, escalating tensions in the Middle East after a brief ceasefire attempt collapsed. President Donald Trump declared the ceasefire 'a waste of time' and 'over', signalling continued US military engagement. Following Trump's remarks, Brent crude oil prices surged 6.3% to $78.8 per barrel, reflecting global supply risk concerns. Four oil and gas tankers turned back from the Strait of Hormuz after vessel attacks, with Iran reportedly ordering ships to avoid the Omani corridor — a development with direct implications for India's energy security and oil imports.", "exam_angle": "Key for GS Paper 2 (IR) — US foreign policy, Middle East geopolitics, and Strait of Hormuz as a chokepoint. Connects to GS Paper 3 (Energy Security) — India's dependence on Gulf oil imports and vulnerability to West Asian conflicts.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["US and Iran exchanged military strikes; Trump declared ceasefire 'over'", "Brent crude rose 6.3% to $78.8 per barrel", "Four oil/LNG tankers turned back from Strait of Hormuz", "Iran ordered ships to avoid Omani corridor"], "source": "NDTV / Reuters / Moneycontrol", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi Visits Prambanan Temple, Unveils India-Indonesia Heritage Plaque; BrahMos Partnership Sealed", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi visited the 1,000-year-old Prambanan Hindu temple complex in Indonesia during his state visit and unveiled a joint India-Indonesia heritage commemorative plaque, highlighting civilisational links between the two nations. Separately, India and Indonesia officially sealed a BrahMos supersonic cruise missile partnership, marking a significant defence export milestone for India. The BrahMos deal with Indonesia had been in negotiation since 2022 and represents India's growing defence export footprint in Southeast Asia.", "exam_angle": "Relevant for GS Paper 2 (IR) — India's Act East Policy, ASEAN relations, and defence diplomacy. The BrahMos export connects to GS Paper 3 (Defence/Sci-Tech) — indigenisation and defence exports under Atmanirbhar Bharat.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi visited Prambanan temple (1,000-year-old Hindu temple, Indonesia) and unveiled India-Indonesia heritage plaque", "India and Indonesia sealed BrahMos supersonic cruise missile partnership", "BrahMos is a joint venture between India's DRDO and Russia's NPO Mashinostroyeniya", "Reflects India's Act East Policy and growing defence exports"], "source": "News18 / The Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi's Australia Visit: 'Rock Star' Welcome Amid Human Rights Protests", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi visited Australia as part of his multi-nation tour, receiving a large-scale welcome from the Indian diaspora described as a 'rock star' reception. The visit also witnessed human rights protests related to the Khalistan issue and the Nijjar murder case. Modi's Australia visit is part of broader efforts to strengthen the Comprehensive Strategic Partnership between India and Australia, which covers trade, defence, education, and critical minerals.", "exam_angle": "Relevant for GS Paper 2 (IR) — India-Australia bilateral relations, Quad grouping, and diaspora diplomacy. Context of the Nijjar case protests adds a layer connecting to India-Canada-Australia diplomatic tensions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi visited Australia as part of multi-nation tour", "India-Australia relationship status: Comprehensive Strategic Partnership", "Australia is a member of the Quad alongside India, USA, and Japan", "Visit coincided with human rights protests over Khalistan issue and Nijjar case"], "source": "The Guardian", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Sensex Sinks 1,680 Points, Nifty Closes Below 23,900 Amid US-Iran Escalation and Global Uncertainty", "category": "economy", "category_name": "Economy & Banking", "summary": "Indian equity markets witnessed a sharp selloff on July 8, 2026, with the BSE Sensex falling approximately 1,680 points and Nifty50 closing below 23,900, a drop of nearly 2%. The primary triggers were Trump's declaration that the US-Iran ceasefire was 'over', rising crude oil prices, and broader global risk-off sentiment. The market crash affected energy, banking, and aviation stocks most severely. This reflects the high sensitivity of Indian markets to geopolitical developments in the Middle East given India's oil import dependence.", "exam_angle": "Relevant for GS Paper 3 (Economy) — transmission of global geopolitical shocks to Indian financial markets, imported inflation via crude oil, and India's current account vulnerability.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Sensex fell ~1,680 points on July 8, 2026", "Nifty50 closed below 23,900 (approx. 2% decline)", "Key trigger: US-Iran military escalation and rising crude oil prices", "Brent crude rose 6.3% to $78.8/barrel on the same day"], "source": "The Economic Times / The Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Russia's Share in India's Oil Imports Crosses 40% in May 2026", "category": "economy", "category_name": "Economy & Banking", "summary": "Russia's share in India's total crude oil imports crossed 40% in May 2026, maintaining its position as India's largest oil supplier even as Indian refiners continue to pay a premium over benchmark prices. This trend, which began after Western sanctions on Russia following the Ukraine invasion in 2022, has reshaped India's oil import basket significantly. The development is occurring against the backdrop of fresh geopolitical tensions in the Middle East, making India's energy diversification strategy critical.", "exam_angle": "Important for GS Paper 3 (Economy/Energy Security) — India's strategic oil sourcing, impact of sanctions on global energy markets, and India's balancing act between Western allies and Russia in energy trade.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Russia's share in India's crude oil imports: >40% in May 2026", "Russia is India's largest single crude oil supplier", "India continues to pay a premium over benchmark prices for Russian oil", "Shift began post-2022 Ukraine invasion and Western sanctions on Russia"], "source": "The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India Urges US to Reconsider Proposed 12.5% Tariff Under USTR Section 301 'Forced Labour' Probe", "category": "economy", "category_name": "Economy & Banking", "summary": "India has formally urged the United States to reconsider a proposed 12.5% additional tariff on Indian goods being considered under USTR's (United States Trade Representative) Section 301 investigation into alleged 'forced labour' practices. This comes amid already stalled India-US bilateral trade deal negotiations. The Section 301 mechanism allows the US to impose trade sanctions in response to practices it deems 'unreasonable or discriminatory'. India's goods exports to the US could be significantly impacted if the tariff is implemented.", "exam_angle": "Key for GS Paper 2 (IR) and GS Paper 3 (Economy) — India-US trade relations, WTO-compatible trade remedy mechanisms, and the broader context of Trump-era tariff policies affecting Indian exports.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US proposed 12.5% tariff on Indian goods under USTR Section 301", "Reason cited: 'Forced labour' practices", "India has formally requested reconsideration", "Section 301 of US Trade Act allows unilateral tariffs on 'unfair' trade practices"], "source": "The Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India-US Trade Deal Remains Stuck Despite Diplomatic Engagement", "category": "economy", "category_name": "Economy & Banking", "summary": "The much-awaited India-US bilateral trade agreement continues to remain stalled, with analysts citing multiple sticking points including US demands on market access for agricultural and dairy products, digital trade norms, and India's data localisation requirements. The ongoing tariff threats under USTR probes have further complicated negotiations. India is the US's largest trading partner in South Asia, and both sides had signalled intent to fast-track a deal.", "exam_angle": "Relevant for GS Paper 2 (IR) and GS Paper 3 (Economy) — India-US trade architecture, protectionism versus liberalisation debate, and India's multilateral and bilateral trade strategy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India-US bilateral trade deal negotiations remain deadlocked", "Key sticking points: agricultural market access, digital trade, data localisation", "India is US's largest South Asian trading partner", "Concurrent USTR tariff threats have complicated the negotiations"], "source": "The New Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "RBI and Tax Department Back Cryptocurrency Ban; Warn of Tax Evasion Risks", "category": "economy", "category_name": "Economy & Banking", "summary": "Documents reviewed by Reuters reveal that India's central bank (RBI) has backed a blanket ban on cryptocurrencies, while the Income Tax Department has separately warned of significant tax evasion risks posed by crypto assets. The RBI's position reflects concerns about financial stability, monetary policy transmission, and capital flight. India currently taxes crypto gains at 30% with a 1% TDS on transactions, but regulatory clarity on the legal status of cryptocurrencies remains pending.", "exam_angle": "Important for GS Paper 3 (Economy) — RBI's monetary policy powers, cryptocurrency regulation debate in India, and digital asset governance. Links to the Cryptocurrency and Regulation of Official Digital Currency Bill.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["RBI has backed a blanket ban on cryptocurrencies", "Income Tax Department warns of tax evasion through crypto", "India currently taxes crypto gains at 30% + 1% TDS on transactions", "Legal/regulatory status of crypto in India remains unresolved"], "source": "Reuters", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Ethanol-Blend Fuel Backlash Intensifies in India; Carmakers Under Scrutiny", "category": "environment", "category_name": "Environment & Ecology", "summary": "A growing backlash against ethanol-blended fuel (particularly E20 — 20% ethanol blend) is intensifying in India, with consumer complaints about reduced engine performance and mileage, and carmakers facing criticism over inadequate adaptation of vehicle technology. India's National Policy on Biofuels targets 20% ethanol blending in petrol by 2025-26 under the Pradhan Mantri JI-VAN Yojana and the Ethanol Blending Programme (EBP). The controversy raises questions about the pace of implementation versus vehicle fleet readiness.", "exam_angle": "Relevant for GS Paper 3 (Environment/Economy) — India's ethanol blending programme, biofuel policy, energy security, and the Pradhan Mantri JI-VAN Yojana. Also links to reducing import dependence on crude oil.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["India targets 20% ethanol blending in petrol (E20) by 2025-26", "Policy instrument: Ethanol Blending Programme (EBP) and PM JI-VAN Yojana", "Consumer backlash: complaints of reduced engine performance and mileage", "Carmakers face scrutiny over inadequate adaptation to E20 fuel standards"], "source": "Reuters", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Wayanad Debris Slip: 5 Missing, Amit Shah Pledges Centre's Support; Environmentalists Demand Halt to Tunnel Works", "category": "environment", "category_name": "Environment & Ecology", "summary": "A fresh debris slip in Wayanad district of Kerala left 5 persons missing, prompting Union Home Minister Amit Shah to pledge full central government support for rescue and relief operations. Environmental groups held the Kerala government accountable and demanded suspension of ongoing tunnel construction works in the ecologically sensitive Western Ghats region. Wayanad has witnessed repeated landslides and debris flows, underscoring the persistent vulnerability of the region to geological hazards, especially during the southwest monsoon season.", "exam_angle": "Key for GS Paper 3 (Environment/Disaster Management) — landslide vulnerability in Western Ghats, NDMA guidelines, and the broader debate over development versus environmental conservation in ecologically sensitive zones (ESZs).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Wayanad district, Kerala (Western Ghats)", "Persons missing after debris slip: 5", "Union Home Minister Amit Shah pledged Centre's support", "Environmentalists demanded suspension of tunnel construction in the region"], "source": "The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Supreme Court Questions Centre Over Blanket Ban on Pregnant IPS Officers During Probation Training", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India questioned the Union Government over a policy that imposes a blanket ban on pregnant IPS (Indian Police Service) officers from undergoing probation training, effectively stalling their career progression. The Court raised concerns that such a policy may violate the constitutional rights of women officers under Articles 14 (equality), 16 (equal opportunity in public employment), and 21 (right to life and personal liberty). The case raises significant questions about gender discrimination in India's civil services training framework.", "exam_angle": "Directly relevant for GS Paper 2 (Polity/Governance) — fundamental rights (Articles 14, 16, 21), gender equality in civil services, and judicial review of executive policies. Also connects to the Maternity Benefit Act and gender-sensitive governance.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Issue: Blanket ban on pregnant IPS officers during probation training", "Supreme Court questioned the Union Government on the policy", "Constitutional provisions at stake: Articles 14, 16, and 21", "IPS is an All India Service governed by the IPS (Cadre) Rules"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Bombay High Court Upholds Woman's Right to Flee Forced Marriage; Invokes Personal Liberty", "category": "polity", "category_name": "Polity & Governance", "summary": "The Bombay High Court protected a woman fleeing a forced marriage, invoking Article 21 (Right to Life and Personal Liberty) and declaring 'Your Life, Your Choice'. The court refused to allow the woman to be returned to her matrimonial home against her will, affirming that individual autonomy and freedom from coercion are fundamental rights under the Constitution. The ruling reinforces a growing body of High Court jurisprudence protecting women's agency in matrimonial matters.", "exam_angle": "Key for GS Paper 2 (Polity) — judicial interpretation of Article 21, fundamental rights, and the right to personal liberty. Connects to gender justice, habeas corpus petitions, and the expanding scope of the right to life.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Court: Bombay High Court", "Constitutional basis: Article 21 (Right to Life and Personal Liberty)", "Ruling: Court protected woman fleeing forced marriage", "Key phrase used by court: 'Your Life, Your Choice'"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Ram Temple Donation Theft: SIT Report Names Avinash Shukla as Prime Accused; Security Lapses Identified", "category": "polity", "category_name": "Polity & Governance", "summary": "A Special Investigation Team (SIT) report on theft of donations at the Ram Temple in Ayodhya has named Avinash Shukla as the prime accused. The SIT found that temple staff stole cash from donation boxes and that security protocols were not enforced. The report highlights systemic failures in the administration of the Ram Janmabhoomi temple, which was consecrated in January 2024. The Shri Ram Janmabhoomi Teerth Kshetra Trust manages the temple complex.", "exam_angle": "Relevant for GS Paper 2 (Governance) — accountability mechanisms in autonomous trusts, management of religious institutions, and the role of SITs in criminal investigation. The Ram Temple is a landmark institution under a government-formed trust.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["SIT named Avinash Shukla as prime accused in Ram Temple donation theft", "SIT found: staff stole cash, security protocols not enforced", "Managing body: Shri Ram Janmabhoomi Teerth Kshetra Trust", "Ram Temple was consecrated in January 2024 in Ayodhya, Uttar Pradesh"], "source": "Scroll.in / The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "NATO Summit: Trump Attacks Spain as 'Terrible Partner', Demands Greenland; Exposes Alliance Cracks", "category": "ir", "category_name": "International Relations", "summary": "At the NATO summit, US President Donald Trump launched a sharp attack on Spain, calling it 'a terrible partner' and threatening to cut off trade, labelling it 'a wasted cause'. Trump simultaneously reiterated demands for control over Greenland, citing its strategic importance for US defence and resource interests amid competition with Russia and China. The summit exposed significant internal divisions within NATO, with Trump questioning the value of collective defence commitments for allies he deems insufficiently compliant.", "exam_angle": "Relevant for GS Paper 2 (IR) — NATO's internal cohesion, US foreign policy under Trump, and Greenland's strategic importance. Connects to Arctic geopolitics and the shifting nature of multilateral alliances.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Trump called Spain 'a terrible partner' and threatened trade cutoff at NATO summit", "Trump reiterated demand for control over Greenland", "Greenland is an autonomous territory of Denmark, strategically located in the Arctic", "Summit exposed cracks in NATO's internal unity"], "source": "The Times of India / Al Jazeera", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Google to Expand AI Data Centres in India; Signals Growing Digital Infrastructure Investment", "category": "scitech", "category_name": "Science & Technology", "summary": "Google's cloud business CEO Thomas Kurian announced that Google will set up more Artificial Intelligence (AI) data centres in India as demand for cloud and AI services grows. This is part of Google's broader global strategy to build AI infrastructure and aligns with India's Digital India and emerging data centre policy framework. The move follows similar announcements by other global tech giants and comes amid India's push to become an AI hub under the IndiaAI Mission.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech/Economy) — India's digital infrastructure development, IndiaAI Mission, data localisation debate, and India's emergence as a global AI hub. Connects to the National Data Governance Framework.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Google to expand AI data centres in India; announced by Cloud CEO Thomas Kurian", "India is targeting becoming a global AI hub under the IndiaAI Mission", "Government of India has a dedicated Digital India programme and National Data Governance Framework", "Reflects growing FDI in India's digital infrastructure sector"], "source": "Livemint", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "China Considering Restrictions on Overseas Access to Advanced AI Models", "category": "scitech", "category_name": "Science & Technology", "summary": "China is reportedly weighing curbs on overseas access to its advanced Artificial Intelligence models, a move that could further fragment the global AI ecosystem and accelerate the AI technology decoupling between China and Western nations. This development comes amid US restrictions on export of advanced semiconductors to China and growing competition between the two nations in AI development. A global report also warned that AI firms worldwide are lagging on safety measures.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech) and GS Paper 2 (IR) — AI governance, technology decoupling between US and China, global AI safety norms, and implications for India's AI strategy and tech diplomacy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["China considering restricting overseas access to its advanced AI models", "Context: Ongoing US-China technology decoupling, US semiconductor export controls", "Separate global report warns AI firms worldwide are lagging on safety measures", "Impacts global AI governance architecture and India's tech partnerships"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Uttar Pradesh Approves Startup Policy 2026 with Focus on $1 Trillion Economy Target", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Uttar Pradesh government under Chief Minister Yogi Adityanath cleared the Startup Policy 2026, aimed at fostering entrepreneurship and innovation in the state with an eye on achieving UP's $1 trillion (₹84 lakh crore) economy goal. The policy is expected to provide incentives including seed funding, incubation support, and regulatory ease for startups. Uttar Pradesh has been aggressively positioning itself as an investment destination following successive Investor Summits.", "exam_angle": "Relevant for GS Paper 3 (Economy) and GS Paper 2 (Governance) — state-level startup ecosystems, economic decentralisation, and the connection between innovation policy and GDP targets. Connects to the national Startup India initiative.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Policy: Uttar Pradesh Startup Policy 2026", "Approved by: Yogi Adityanath-led UP government", "Target: Support UP's $1 trillion economy goal", "Key features: Seed funding, incubation support, regulatory ease"], "source": "India Today", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Lashkar-e-Taiba Commander Killed in Shopian Encounter, J&K", "category": "defence", "category_name": "Defence & Security", "summary": "A Lashkar-e-Taiba (LeT) commander who had been trapped in South Kashmir's Shopian district for four days was killed in a security forces encounter. Police confirmed the elimination of the LeT militant, with a search operation continuing for a second militant. The operation is part of ongoing counter-insurgency efforts by the Indian Army, CRPF, and J&K Police in the Kashmir Valley, where LeT remains one of the most active Pakistan-based terrorist organisations.", "exam_angle": "Relevant for GS Paper 3 (Internal Security) — counter-terrorism operations in J&K, Lashkar-e-Taiba's operational presence, and the role of unified command structure in J&K security operations.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Outfit: Lashkar-e-Taiba (LeT), a Pakistan-based terrorist organisation", "Location: Shopian district, South Kashmir", "LeT commander killed after 4-day siege/encounter operation", "Operation involved: Indian Army, J&K Police (unified command)"], "source": "NDTV / The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi Visits 1,000-Year-Old Prambanan Temple in Indonesia: Cultural Diplomacy and Heritage Linkages", "category": "culture", "category_name": "Art & Culture", "summary": "Prime Minister Narendra Modi visited the Prambanan temple complex in Yogyakarta, Indonesia — a UNESCO World Heritage Site and one of the largest Hindu temple complexes in Southeast Asia, dating back to the 9th-10th century CE. Modi unveiled a joint India-Indonesia heritage plaque, emphasising the deep cultural and civilisational links between the two nations rooted in Hinduism, Sanskrit literature, and the Ramayana tradition. The visit underlines India's use of cultural diplomacy as a tool of soft power in the Indo-Pacific region.", "exam_angle": "Relevant for GS Paper 1 (Culture) — India's cultural links with Southeast Asia, Hindu temple architecture abroad, and UNESCO World Heritage Sites. Also connects to GS Paper 2 (IR) — India's soft power diplomacy and cultural outreach.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Prambanan: UNESCO World Heritage Site, located in Yogyakarta, Indonesia", "Age: ~1,000 years (built circa 9th-10th century CE), dedicated to the Hindu Trimurti", "PM Modi unveiled India-Indonesia joint heritage plaque during visit", "Prambanan reflects Hindu-Buddhist cultural influence in Southeast Asia (Indianisation)"], "source": "News18", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India–Indonesia Defence Deal: BrahMos and Astra Missiles to Be Supplied to Indonesia", "category": "defence", "category_name": "Defence & Security", "summary": "India is set to supply BrahMos supersonic cruise missiles and Astra air-to-air missiles to Indonesia, confirmed by an Indian government official during PM Modi's state visit to Jakarta. This marks a significant expansion of India's defence exports under its 'Make in India' and defence export push. The deal is part of a broader strategic partnership being formalised between the two countries. Indonesia becomes one of the key Southeast Asian nations to acquire the BrahMos system, which is jointly developed by India and Russia.", "exam_angle": "Relevant to GS Paper 2 (IR/Defence) — India's defence export ambitions, BrahMos as a strategic product, and deepening ties with ASEAN nations under Act East Policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Missiles: BrahMos (supersonic cruise) and Astra (air-to-air)", "BrahMos is a joint venture between India (DRDO/BrahMos Aerospace) and Russia", "Indonesia is an ASEAN nation; deal part of India's Act East Policy", "Announced during PM Modi's state visit to Jakarta (July 2026)"], "source": "Reuters / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Visits Indonesia: IIM Campus, UPI, AI, Critical Minerals and EVM Cooperation Announced", "category": "ir", "category_name": "International Relations", "summary": "PM Narendra Modi visited Jakarta, Indonesia, heralding what he called a 'golden chapter' in India–Indonesia relations. Key announcements included setting up an IIM Bangalore campus in Indonesia, extending UPI payment infrastructure, cooperation on artificial intelligence and critical minerals, and an MoU on election management including export of customised Electronic Voting Machines (EVMs). PM Modi also received Indonesia's highest civilian honour, the 'Bintang Adipurna'. PM Modi highlighted the next 25 years as crucial for the bilateral partnership and the Indian Ocean region.", "exam_angle": "Tests knowledge of India's bilateral diplomacy, Act East Policy, defence/tech exports, and India's soft power through institutions like IIMs. The EVM export MoU is significant for polity questions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Award received: 'Bintang Adipurna' — Indonesia's highest state honour", "IIM Bangalore to set up campus in Indonesia", "MoU on election management and export of customised EVMs signed", "Cooperation areas: UPI, AI, critical minerals, satellite launch capability, defence"], "source": "The Times of India / News18 / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Offers Indonesia Satellite Launch Capability; Deepens Space Partnership", "category": "scitech", "category_name": "Science & Technology", "summary": "During PM Modi's visit to Jakarta, India offered Indonesia satellite launch capability as part of deepening the bilateral space partnership. This aligns with ISRO's expanding commercial launch services under NewSpace India Limited (NSIL). The offer reflects India's growing role as a provider of space services to developing and partner nations in the Indo-Pacific region. Space cooperation was among multiple high-tech areas announced during the summit.", "exam_angle": "Links to ISRO's commercial arm NSIL, India's space diplomacy, and the broader theme of India as a space-faring nation offering services to allies.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["India offered satellite launch capability to Indonesia", "ISRO's commercial arm: NewSpace India Limited (NSIL)", "Part of India–Indonesia summit outcomes, July 2026", "Relevant to India's Act East Policy and space diplomacy"], "source": "News18", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "2008 Ahmedabad Serial Blasts Case: Gujarat High Court Upholds Death Penalty for 38 Convicts", "category": "polity", "category_name": "Polity & Governance", "summary": "The Gujarat High Court upheld the death penalty for 38 convicts in the 2008 Ahmedabad serial blasts case, which involved a series of bomb explosions across the city that killed over 56 people and injured hundreds. The government described the verdict as a 'historic victory'. The case involved one of the largest terrorist attacks in India and the trial court had earlier awarded the death sentence to 38 and life imprisonment to others. The High Court confirmation is a necessary step before the matter can go to the Supreme Court.", "exam_angle": "Relevant to criminal law, capital punishment jurisprudence, and constitutional provisions on the right to life (Article 21). Also tests knowledge of India's counter-terrorism legal framework.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Incident: 2008 Ahmedabad serial bomb blasts (56+ killed)", "Court: Gujarat High Court upheld death penalty", "Number of convicts on death row confirmed: 38", "Mandatory confirmation of death sentences by High Court under CrPC before Supreme Court appeal"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "E20 Petrol Row: Supreme Court Takes Up Petition; Concerns Over Damage to E10 Vehicles", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report and a Supreme Court petition have raised concerns that E20 petrol (containing 20% ethanol blended with petrol) may damage rubber fuel system components in older vehicles designed for E10 (10% ethanol blend). A litigant before the Supreme Court alleged 'silent compulsion' in the E20 rollout. India is pursuing its ethanol blending programme — achieving 20% blending by 2025–26 — as part of its energy security and climate commitments. Petroleum Minister Hardeep Puri defended the programme, saying car manufacturers are comfortable with the transition.", "exam_angle": "Connects to India's National Biofuel Policy, ethanol blending targets, energy security, and the intersection of environmental policy with consumer rights.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["E20 = 20% ethanol blended petrol; E10 = 10% ethanol blend", "India's target: 20% ethanol blending by 2025–26 under National Biofuel Policy 2018", "Concern: E20 may damage rubber parts in E10-compatible vehicles", "Matter raised before the Supreme Court of India"], "source": "Moneycontrol / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Wayanad Landslide: IMD Red Alert, 5 Dead; Kerala Ministers Term It 'Man-Made Disaster'", "category": "environment", "category_name": "Environment & Ecology", "summary": "A landslide struck Wayanad district in Kerala following heavy rainfall, killing at least 5 people and prompting a red alert from the India Meteorological Department (IMD). Two Kerala ministers termed the disaster 'man-made', raising questions about construction activity and deforestation in the ecologically sensitive Western Ghats. Wayanad was the site of a catastrophic landslide in July 2024 as well, making it a region of recurring disaster vulnerability. Simultaneously, the IMD issued red alerts for Delhi and an orange alert for Mumbai as the monsoon intensified across India.", "exam_angle": "Relevant to disaster management, Western Ghats ecology, Gadgil and Kasturirangan Committee recommendations on ecologically sensitive zones, and IMD's alert system.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Wayanad, Kerala — ecologically sensitive part of Western Ghats", "Deaths: At least 5 in the latest landslide", "IMD alert levels: Red (extreme), Orange (very heavy), Yellow (heavy rainfall) — colour-coded system", "Kerala ministers attributed the disaster to human activity ('man-made')"], "source": "The Hindu / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Strait of Hormuz Tanker Attacks: Three Commercial Ships Hit, Oil Prices Rise", "category": "ir", "category_name": "International Relations", "summary": "The United Kingdom Maritime Trade Operations (UKMTO) reported that three commercial tankers were hit by unidentified projectiles in the Strait of Hormuz, with no casualties reported. Oil prices rose on reports of the attack, which was attributed to Iranian-linked activity by media reports. The Strait of Hormuz is one of the world's most critical oil chokepoints, through which roughly 20% of global oil trade passes. The attacks are part of ongoing escalation in the West Asia/Middle East region.", "exam_angle": "Strait of Hormuz is a critical chokepoint for global energy security and directly impacts India's oil import costs. Relevant to GS Paper 2 (IR) and GS Paper 3 (Economy — energy security).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Location: Strait of Hormuz — between Iran and Oman", "~20% of global oil trade passes through the Strait of Hormuz", "Reporting authority: UKMTO (UK Maritime Trade Operations)", "Three tankers hit; oil prices rose on news of attacks"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Macron Visits Syria: Blast Near Damascus Hotel During French Presidential Visit", "category": "ir", "category_name": "International Relations", "summary": "French President Emmanuel Macron made a state visit to Damascus, Syria — a significant diplomatic visit marking engagement with Syria's new post-Assad government. During the visit, a blast was reported near his hotel, though Macron was unharmed. The visit signalled Western re-engagement with Syria following the fall of Bashar al-Assad's government. France's diplomatic outreach to Syria is part of broader international efforts to stabilise the country and address the refugee and humanitarian crisis.", "exam_angle": "Relevant to GS Paper 2 (IR) — geopolitics of West Asia, France's foreign policy, and Syria's post-conflict political transition.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["French President Macron visited Damascus, Syria", "Blast reported near his hotel during the visit; Macron was unharmed", "Significance: Western diplomatic re-engagement with post-Assad Syria", "Syria's Assad government fell in late 2024 after rebel offensive"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "UNICEF: Over 300 Children Killed or Wounded in Sudan War in Six Months", "category": "ir", "category_name": "International Relations", "summary": "UNICEF reported that over 300 children have been killed or wounded in Sudan's ongoing civil war over a period of six months, highlighting the severe humanitarian toll of the conflict between the Sudanese Armed Forces (SAF) and the Rapid Support Forces (RSF). The Sudan conflict, which began in April 2023, has created one of the world's largest displacement crises. UNICEF's report underscores the violation of international humanitarian law and the targeting of civilian infrastructure in the war.", "exam_angle": "Relevant to GS Paper 2 (IR) — international organisations (UNICEF), humanitarian law, and Africa-related current affairs that frequently appear in UPSC Prelims.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["300+ children killed or wounded in Sudan conflict over 6 months: UNICEF", "Sudan conflict: SAF vs RSF (Rapid Support Forces), began April 2023", "One of the world's largest displacement/humanitarian crises", "UNICEF is a UN agency focused on children's welfare (HQ: New York)"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Trump Considers Selling F-35 Fighter Jets to Turkey", "category": "defence", "category_name": "Defence & Security", "summary": "US President Donald Trump stated that the United States would consider selling F-35 stealth fighter jets to Turkey. Turkey was originally part of the F-35 programme but was removed in 2019 after it purchased Russia's S-400 air defence system, triggering US sanctions under CAATSA (Countering America's Adversaries Through Sanctions Act). Trump's statement signals a possible shift in US policy and a potential easing of tensions with Turkey, a NATO ally. The development is significant for NATO cohesion and US arms export policy.", "exam_angle": "Connects to CAATSA (relevant because India also purchased S-400 from Russia), NATO dynamics, and US arms export policy — all frequent UPSC IR themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["F-35 is a 5th-generation stealth multirole fighter (Lockheed Martin)", "Turkey was expelled from F-35 programme in 2019 after S-400 purchase from Russia", "CAATSA (Countering America's Adversaries Through Sanctions Act) was the sanctions basis", "India also purchased S-400 from Russia and faced CAATSA waiver pressure"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Ukraine Strikes 8 Russian 'Shadow Fleet' Tankers Delivering Fuel to Crimea", "category": "ir", "category_name": "International Relations", "summary": "Ukraine conducted strikes on eight Russian 'shadow fleet' tankers that were delivering fuel to Crimea, which Russia annexed in 2014. The 'shadow fleet' refers to vessels used by Russia to circumvent Western oil sanctions imposed after the 2022 invasion of Ukraine. Targeting of these tankers represents Ukraine's strategy to disrupt Russian fuel supply lines, especially to occupied territories. The development has implications for global shipping insurance and maritime security.", "exam_angle": "Relevant to the Russia-Ukraine conflict, Western sanctions architecture, the concept of 'shadow fleets', and energy security — all important for GS Paper 2 IR and GS Paper 3 Economy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["'Shadow fleet': vessels used to evade Western oil sanctions on Russia", "Crimea was annexed by Russia in 2014; internationally recognised as Ukrainian territory", "Eight tankers struck by Ukraine in this operation", "Western sanctions cap Russian oil at $60/barrel under G7 Price Cap mechanism"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "TribeX Digital Learning Platform for Tribal Arts and Culture Launched by Union Tribal Affairs Minister", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Union Minister for Tribal Affairs Jual Oram launched 'TribeX', a digital learning platform dedicated to tribal arts, culture, and traditional knowledge. The platform is designed to preserve, promote, and disseminate India's rich tribal heritage in a digital format, making it accessible to tribal communities and the wider public. The launch aligns with the Ministry of Tribal Affairs' mandate to protect tribal identities and livelihoods under constitutional provisions (Articles 15, 16, 46, and the Fifth and Sixth Schedules).", "exam_angle": "Relevant to GS Paper 2 (Schemes/Welfare) — government initiatives for tribal welfare, digital empowerment, and constitutional safeguards for Scheduled Tribes.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Platform name: TribeX", "Launched by: Union Minister Jual Oram, Ministry of Tribal Affairs", "Purpose: Digital learning for tribal arts, culture, and traditional knowledge", "Relevant constitutional provisions: Articles 46, Fifth Schedule, Sixth Schedule (NE India)"], "source": "PIB", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Taj Mahal–Tejo Mahalaya Petition: Allahabad High Court Issues Notice to Centre", "category": "culture", "category_name": "Art & Culture", "summary": "The Allahabad High Court issued a notice to the Central Government on a petition claiming that the Taj Mahal was built on a pre-existing Hindu temple site called 'Tejo Mahalaya'. The petition seeks a court-directed investigation into the historical claims. The Taj Mahal, built by Mughal Emperor Shah Jahan in the 17th century in Agra, is a UNESCO World Heritage Site and one of India's most iconic monuments. Similar petitions in the past have been dismissed by courts.", "exam_angle": "Relevant to heritage/culture questions, Places of Worship (Special Provisions) Act 1991, and constitutional provisions on religious sites — a recurring issue in UPSC current affairs.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Monument: Taj Mahal, Agra — UNESCO World Heritage Site (designated 1983)", "Built by: Mughal Emperor Shah Jahan (17th century) in memory of Mumtaz Mahal", "Petition claims: Taj Mahal built over 'Tejo Mahalaya' Hindu temple site", "Court: Allahabad High Court issued notice to Centre"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "ZEE5 Removes 'Satluj' (Punjab 95) After Government Cites IT Rules and Security Concerns", "category": "polity", "category_name": "Polity & Governance", "summary": "OTT platform ZEE5 removed the film 'Satluj' (based on the Diljit Dosanjh-produced 'Punjab 95', depicting the human rights situation during the 1984–95 Punjab militancy period) after the government cited security concerns and the IT Rules 2021 as grounds for the takedown. The film had previously been held up by the Central Board of Film Certification (CBFC). SGPC and Shiromani Akali Dal condemned the removal. The case raises questions about OTT regulation, freedom of expression, and government powers under the IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — OTT regulation under IT Rules 2021, CBFC's powers, freedom of speech (Article 19(1)(a)), and reasonable restrictions.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Film: 'Satluj' (Punjab 95) — depicts 1984–95 Punjab militancy and human rights issues", "Platform: ZEE5 removed the film citing government direction", "Legal basis cited: IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021", "Regulatory body: CBFC (Central Board of Film Certification) had earlier withheld certification"], "source": "The Indian Express", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Pakistan Issues 'War' Threat Over Indus Waters Amid Suspended Treaty", "category": "ir", "category_name": "International Relations", "summary": "Pakistan issued statements threatening war with India over Indus Waters, amid the monsoon season when river flows are high and following India's suspension of the Indus Waters Treaty (IWT) after the Pahalgam terrorist attack in April 2025. India suspended the 1960 Indus Waters Treaty — brokered by the World Bank — as a retaliatory measure. The IWT governs the sharing of six rivers of the Indus system between India and Pakistan, with the western rivers (Indus, Jhelum, Chenab) allocated to Pakistan and eastern rivers (Ravi, Beas, Sutlej) to India.", "exam_angle": "Critical for GS Paper 2 (IR) — Indus Waters Treaty, India–Pakistan relations, water diplomacy, and World Bank's role as a mediator/guarantor.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty (IWT) signed in 1960 — brokered by World Bank", "Western rivers (Indus, Jhelum, Chenab) allocated to Pakistan; Eastern (Ravi, Beas, Sutlej) to India", "India suspended IWT after Pahalgam terror attack (April 2025)", "Pakistan threatened war over Indian actions on Indus water flows"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Bengaluru Startup's Surveillance Satellite Knocked Out by Solar Activity", "category": "scitech", "category_name": "Science & Technology", "summary": "A surveillance satellite operated by a Bengaluru-based startup was knocked out of service due to intense solar activity (likely a geomagnetic storm or solar flare), with the company vowing to make a comeback. The incident highlights the vulnerability of low-Earth orbit (LEO) satellites to space weather events. India's private space sector has been growing rapidly following the liberalisation of the space sector through the Indian Space Policy 2023 and the establishment of IN-SPACe (Indian National Space Promotion and Authorisation Centre).", "exam_angle": "Relevant to India's private space sector, IN-SPACe, space weather hazards, and the broader theme of space security and satellite vulnerability.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Incident: Solar activity (geomagnetic storm/solar flare) disabled a surveillance satellite", "Operator: Bengaluru-based private space startup", "Regulatory body for Indian private space sector: IN-SPACe (under DoS)", "Indian Space Policy 2023 opened space sector to private players"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India's Semiconductor (Chip) Manufacturing Push Faces Execution Challenges", "category": "economy", "category_name": "Economy & Banking", "summary": "An analysis highlights that India's semiconductor manufacturing ambitions face the biggest challenge not in policy design but in execution — including lack of specialised talent, supply chain gaps, water and power requirements, and delays in facility construction. India has approved semiconductor projects under the India Semiconductor Mission (ISM), including facilities by Tata Electronics (in Dholera, Gujarat) and Micron Technology (ATMP facility in Sanand, Gujarat). The global chip race is intensifying with the US CHIPS Act and EU Chips Act offering competing incentives.", "exam_angle": "Directly relevant to GS Paper 3 (Economy/Sci-Tech) — India Semiconductor Mission, Atmanirbhar Bharat in electronics, and critical technology supply chains.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India Semiconductor Mission (ISM) launched under MeitY with Rs 76,000 crore incentive package", "Approved projects: Tata Electronics (Dholera, Gujarat) and Micron Technology ATMP (Sanand, Gujarat)", "Key challenge highlighted: Execution — talent, supply chain, infrastructure", "Global context: US CHIPS Act ($52 bn) and EU Chips Act competing for semiconductor investment"], "source": "The Times of India", "day": "2026-07-07", "day_label": "07 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "culture", "name": "Art & Culture"}]};